package cl.dynasty.nexusbeacon.platform.classic;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.Path;import java.util.Collections;import java.util.UUID;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class ClassicYamlBeaconStorageTest {@TempDir Path temp;@Test void roundTripsExistingSchemaFields(){ClassicYamlBeaconStorage s=new ClassicYamlBeaconStorage(temp.resolve("storage.yml").toFile());ClassicBeaconRecord r=new ClassicBeaconRecord(new ClassicBeaconLocation("world",3,70,4),UUID.randomUUID(),UUID.randomUUID(),64,2,Collections.singletonMap("speed",Integer.valueOf(2)),Collections.singleton("speed"),Collections.singleton(UUID.randomUUID()),true,"aqua",true,"FLAME");s.store(Collections.singleton(r));ClassicStorageLoad load=s.load();assertTrue(load.isSuccessful());assertEquals(r,load.getRecords().get(0));}}
